from PIL import Image
import numpy as np
from collections import deque
im = Image.open('mol_0004.png').convert('L')
a = np.array(im); mask=a<128
H,W=mask.shape
lab=-np.ones((H,W),int); comps=[]; cur=0
for i in range(H):
    for j in range(W):
        if mask[i,j] and lab[i,j]<0:
            q=deque([(i,j)]); lab[i,j]=cur; pix=[]
            while q:
                y,x=q.popleft(); pix.append((y,x))
                for dy in(-1,0,1):
                    for dx in(-1,0,1):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and mask[ny,nx] and lab[ny,nx]<0:
                            lab[ny,nx]=cur; q.append((ny,nx))
            comps.append(pix); cur+=1
for k in [18,27,29,30,31,33,34,37,11,13,14]:
    pix=comps[k]
    ys=[p[0] for p in pix]; xs=[p[1] for p in pix]
    print('comp',k,'bbox x',min(xs),max(xs),'y',min(ys),max(ys))
    for y in range(min(ys),max(ys)+1):
        row=''.join('#' if mask[y,x] else '.' for x in range(min(xs),max(xs)+1))
        print(f'   {y:3d} '+row)
