import numpy as np
def read(f):
    lines=open(f).read().split('\n'); n=int(lines[0]); els=[]; xyz=[]
    for l in lines[2:2+n]:
        p=l.split(); els.append(p[0]); xyz.append([float(v) for v in p[1:4]])
    return els, np.array(xyz)
els,xyz=read('opt2.xyz')
d=np.linalg.norm(xyz[:,None]-xyz[None,:],axis=-1); np.fill_diagonal(d,99)
# nonbonded closest contacts
pairs=[]
for i in range(len(els)):
    for j in range(i+1,len(els)):
        pairs.append((d[i,j],i,j))
pairs.sort()
cnt=0
for dd,i,j in pairs:
    if dd<1.6:
        print(round(dd,2), i, els[i], j, els[j]); cnt+=1
    if cnt>25: break
def ang(i,j,k):
    a=xyz[i]-xyz[j]; b=xyz[k]-xyz[j]
    return round(float(np.degrees(np.arccos(a@b/np.linalg.norm(a)/np.linalg.norm(b)))),1)
print('P1-Ru-Si',ang(2,0,1),'P2-Ru-Si',ang(3,0,1),'P1-Ru-P2',ang(2,0,3))
print('P3-Ru-Si',ang(4,0,1),'P3-Ru-P1',ang(4,0,2),'P3-Ru-P2',ang(4,0,3))
mid=(xyz[26]+xyz[27])/2
print('P3-Ru-C2mid',ang(4,0,99) if False else round(float(np.degrees(np.arccos(np.dot(xyz[4]-xyz[0],mid-xyz[0])/np.linalg.norm(xyz[4]-xyz[0])/np.linalg.norm(mid-xyz[0])))),1))
print('Si-Ru-C2mid',round(float(np.degrees(np.arccos(np.dot(xyz[1]-xyz[0],mid-xyz[0])/np.linalg.norm(xyz[1]-xyz[0])/np.linalg.norm(mid-xyz[0])))),1))
